  "Yapay zekâ şu an yanıt veremiyor. Biraz sonra tekrar dene.": "The AI cannot reply right now. Try again in a little while.",
  "Boş yanıt geldi, tekrar dene.": "An empty reply came back, try again.",
  "İstek çok büyük.": "The request is too large.",
  "Geçersiz istek.": "Invalid request.",
  "Yetkisiz.": "Unauthorized.",
  "Bulunamadı.": "Not found.",
  "Yanıt çok gecikti. Tekrar dene.": "The reply took too long. Try again.",
  "Yanıt alınamadı, tekrar dene.": "No reply received, try again.",
  "Gerçek yapay zekâ kapatıldı. Demo yanıtlar kullanılacak.": "Real AI turned off. Demo replies will be used.",
  "Hafıza nerede tutulur?": "Where is memory kept?",
  "Burada yazanlar yalnızca bu cihazda, bu projenin içinde saklanır ve JSON yedeğine girer. Başka projelerle karışmaz. Yapay zekâ konuştuğun her cümleyi saklamaz: kalıcı bilgi ancak sen \"Kaydet\" dersen veya kendin eklersen girer.": "What you write here is stored only on this device, inside this project, and is included in the JSON backup. It is not mixed with other projects. The AI does not store every sentence you say: lasting information is added only if you say \"Save\" or add it yourself.",
  "Yapay zekâ sunucusuyla paylaşım": "Sharing with the AI server",
  "Sohbette bu projenin özetini sunucuya gönder": "Send this project's summary to the server in chat",
  "Gerçek yapay zekâyı henüz sen açmadığın için kullanılmıyor; hiçbir şey dışarı gönderilmiyor. Bu ayar, gerçek yapay zekâyı açarsan geçerli olur.": "The real AI is not used because you have not turned it on yet; nothing is sent outside. This setting applies if you turn on the real AI.",
  "Projeden hesaplananlar": "Calculated from the project",
  "Bunlar kaydedilmez; her seferinde projenin güncel durumundan hesaplanır, bu yüzden eskimez.": "These are not saved; they are calculated from the project's current state each time, so they never go stale.",
  "Görev ilerlemesi": "Task progress",
  "Sıradaki görev": "Next task",
  "Kayıtlı bilgiler": "Saved information",
  "Henüz kayıtlı bilgi yok. Aşağıdan kendin ekleyebilir ya da sohbette önemli bir kararını yazınca çıkan öneriyi onaylayabilirsin.": "No saved information yet. You can add some yourself below, or approve the suggestion that appears when you write an important decision in the chat.",
  "Bilgi ekle": "Add information",
  "Tür": "Type",
  "Hedef": "Goal",
  "Karar": "Decision",
  "Tercih": "Preference",
  "Son nokta": "Latest point",
  "Bilgi": "Information",
  "Şifre, PIN, kart/IBAN ve kimlik numarası gibi hassas bilgiler kaydedilmez.": "Sensitive information such as passwords, PINs, card/IBAN and ID numbers is not saved.",
  "Hafızayı temizle": "Clear memory",
  "Yalnızca bu projenin kayıtlı bilgilerini ve onay bekleyen önerilerini siler. Görevler, notlar, gelir-gider kayıtları ve sohbet geçmişi silinmez. Onay istenir.": "Deletes only this project's saved information and pending suggestions. Tasks, notes, income-expense records and chat history are not deleted. You will be asked to confirm.",
  "Bu projenin hafızasını temizle": "Clear this project's memory",
  "Hafıza, \"Geçmiş İşlemler\"den farklıdır: Geçmiş İşlemler yaptığın çalışmaların arşividir ve yapay zekâya talimat olarak verilmez.": "Memory is different from \"Past Actions\": Past Actions is an archive of the work you have done and is not given to the AI as instructions.",
  "Örn: Önce Instagram ile başlamaya karar verdim": "E.g. I decided to start with Instagram first",
  "Şu an gerçek bir yapay zekâ sunucusu bağlı değil; hiçbir şey dışarı gönderilmiyor. Bu ayar, sunucu bağlanırsa geçerli olur.": "No real AI server is connected right now; nothing is sent outside. This setting applies if a server is connected.",
  "Bu sohbet ve hafıza yalnızca bu projeye aittir; başka projelerin bilgisi karışmaz. Bilgiler cihazında tutulur. Proje özetin sunucuya gönderilmez.": "This chat and memory belong only to this project; other projects' information is not mixed in. The information is kept on your device. Your project summary is not sent to the server.",
  "Açıkken, bu projedeki sohbetlerde aşağıdaki özet (serbest notların ve gelir-gider kayıtların hariç) yanıt hazırlanırken sunucuya gidebilir. Kapalıyken hiçbir şey gitmez.": "When on, the summary below (excluding your free notes and income-expense records) may be sent to the server while preparing replies in this project's chats. When off, nothing is sent.",
  "Bu sohbet ve hafıza yalnızca bu projeye aittir; başka projelerin bilgisi karışmaz. Bilgiler cihazında tutulur. Proje özetin, yanıt hazırlanırken yapay zekâ sunucusuna gönderilir (Hafıza ekranından kapatabilirsin).": "This chat and memory belong only to this project; other projects' information is not mixed in. The information is kept on your device. Your project summary is sent to the AI server while a reply is being prepared (you can turn this off on the Memory screen).",
  "Planlandı": "Planned",
