  "Ödeme entegrasyonu yok.": "No payment integration.",
  "İçerik yayımlama": "Publishing content",
  "Bağlı hesap yok; yayımlama yapılmaz.": "No connected account; nothing is published.",
  "Mesaj veya e-posta gönderme": "Sending messages or e-mail",
  "Bağlı hesap yok; gönderim yapılmaz.": "No connected account; nothing is sent.",
  "Hesap ayarlarını değiştirme": "Changing account settings",
  "Bağlı hesap yok.": "No connected account.",
  "Verini paylaşma": "Sharing your data",
  "Veri paylaşımı yapılmaz.": "Your data is not shared.",
  "Verini silme (yapay zekâ eliyle)": "Deleting your data (by the AI)",
  "Verini yalnızca sen silebilirsin.": "Only you can delete your data.",
  "Harici hesapta değişiklik": "Changes on an external account",
  "OAuth/API entegrasyonu yok.": "No OAuth/API integration.",
  "Hedefini bir görev planına böldüm (demo yapay zekâ: kural tabanlı şablon, gerçek model yazmadı). Plan şimdilik yalnızca TASLAK; aşağıdaki karttan onaylarsan görevler başlatılabilir, onaylamazsan hiçbiri çalışmaz. Para harcama, yayımlama veya mesaj gönderme gibi adımlar için ayrıca onayını isterim; bu sürümde dış hesaplara bağlı olmadığım için bunları yapamam.": "I split your goal into a task plan (demo AI: rule-based template, no real model wrote it). For now the plan is only a DRAFT; if you approve it in the card below the tasks can be started, if you don't, none of them runs. For steps like spending money, publishing or sending messages I will ask for your approval separately; in this version I am not connected to any outside account, so I cannot do them.",
  "Görev planı bir projeye bağlı olmalı. Genel sohbetteyken plan oluşturmuyorum; \"Proje sohbeti\"ne geçip (veya bir proje başlatıp) hedefini tekrar yaz.": "A task plan must belong to a project. I don't create plans in the general chat; switch to \"Project chat\" (or start a project) and write your goal again.",
  "Bilinmeyen yetenek.": "Unknown capability.",
  "Bu sürümde bu işlem için bir bağlantı yok; izin verilemez.": "There is no connection for this action in this version; permission cannot be granted.",
  "Proje bulunamadı veya arşivde; görevleri değiştirilemez.": "Project not found or archived; its tasks cannot be changed.",
  "Hedefi biraz daha açık yaz (en az # karakter).": "Write the goal a bit more clearly (at least # characters).",
  "Şifre, PIN, kart/IBAN veya kimlik numarası gibi bilgiler hedefe yazılmamalı.": "Information such as passwords, PINs, card/IBAN or ID numbers must not be written in the goal.",
