  "Yalnızca tamamlanan, başarısız veya iptal edilen görev silinebilir.": "Only a completed, failed or cancelled task can be deleted.",
  "Görev merkezi": "Task center",
  "# açık · # onay bekliyor": "# open · # waiting for approval",
  "Yapay zekâ destekli görev planı. Her adım senin onayınla ilerler.": "AI-assisted task plan. Every step moves forward only with your approval.",
  "Görev merkezine git": "Go to the task center",
  "Görev Merkezi": "Task Center",
  "# açık": "# open",
  "Akış: planla → hazırla → seçenek sun → onay al → desteklenen işlemi yap → raporla. Burada yapay zekâ kendi başına işlem yapmaz; her adımı sen onaylarsın. Görevler yalnızca bu projeye aittir.": "Flow: plan → prepare → offer options → get approval → do the supported action → report. The AI does nothing on its own here; you approve every step. Tasks belong only to this project.",
  "Onay bekleyenler": "Waiting for approval",
  "Şu an onayını bekleyen bir işlem yok.": "No action is waiting for your approval right now.",
  "Henüz görev yok. Sohbette \"Dijital ürün projemi geliştirmek istiyorum\" gibi bir hedef yaz, plan taslağı hazırlansın; ya da aşağıdan kendin görev ekle.": "No tasks yet. Write a goal like \"I want to grow my digital product project\" in the chat and a plan draft will be prepared, or add a task yourself below.",
  "Sohbete git": "Go to chat",
  "Yeni görev": "New task",
  "Görev adı": "Task name",
  "Öncelik": "Priority",
  "Dış işlemler ve izinler": "External actions and permissions",
  "Bu sürümde hiçbir dış hesaba (sosyal medya, e-posta, ödeme, web sitesi) bağlı değilim ve şifre/OAuth istemem. Aşağıdaki işlemler yapılmaz; yalnızca taslak hazırlanır. İleride bir bağlantı eklenirse her biri ayrı izinle ve her seferinde onayınla çalışır.": "In this version I am not connected to any outside account (social media, e-mail, payment, website) and I never ask for passwords/OAuth. The actions below are not performed; only drafts are prepared. If a connection is added later, each one will work with a separate permission and with your approval every time.",
  "Bu cihazda": "On this device",
  "Bağlı değil": "Not connected",
  "Paket:": "Package:",
  "tüm paketlerde şimdilik aynı temel görev motoru kullanılır.": "the same basic task engine is used in all packages for now.",
