  "Yapay zekâ (demo, kural tabanlı) planı hazırladı. Onayını bekliyor.": "The AI (demo, rule-based) prepared the plan. Waiting for your approval.",
  "Açıklama": "Description",
  "Sonuç / çıktı (kendi notun)": "Result / output (your own note)",
  "Kime hizmet edeceğini netleştirmek için araştırma soru listesi taslağı hazırla.": "Prepare a draft question list for research to clarify who you will serve.",
  "Bağımlı olduğu görevler:": "Depends on these tasks:",
  "Projenin gelir modeline uygun ürün/içerik fikirleri taslağı çıkar.": "Draft product/content ideas that fit the project's income model.",
  "Dört haftalık bir geliştirme iskeleti hazırla. Yaklaşımı sen seçersin.": "Prepare a four-week development outline. You choose the approach.",
  "Hangi yaklaşımla ilerleyelim?": "Which approach should we take?",
  "İki yaklaşım var; ikisinde de sonuç garanti değildir.": "There are two approaches; neither guarantees a result.",
  "A: Düşük maliyet, yavaş ilerleme": "A: Low cost, slow progress",
