  "Senin onayını bekliyor: Hangi yaklaşımla ilerleyelim?": "Waiting for your approval: Which approach should we take?",
  "Tanıtım gönderileri için taslaklar hazırla. Yayımlama ayrı bir onay ister ve şu an yapılamaz.": "Prepare drafts for promotion posts. Publishing needs a separate approval and cannot be done right now.",
  "Taslakların yayımlanması": "Publishing the drafts",
  "Hazırlanan taslakları yayımlamak istiyor musun?": "Do you want to publish the prepared drafts?",
  "Yayımlamayı onaylıyorum": "I approve publishing",
  "Bu işlem yapılmadı:": "This action was not performed:",
  "Bağlı hesap yok; yayımlama yapılmaz. Taslak hazır; işlemi sen kendin yapabilirsin.": "No connected account; nothing is published. The draft is ready; you can do the action yourself.",
  "Ben yaptım, tamamla": "I did it, complete",
  "Düzenle": "Edit",
  "Başarısız say": "Mark as failed",
  "İptal et": "Cancel",
  "Onay kaydedildi, ama \"İçerik yayımlama\" bu sürümde desteklenmiyor: HİÇBİR İŞLEM YAPILMADI. Taslak hazırlık aşamasında tutuluyor.": "Approval recorded, but \"Publishing content\" is not supported in this version: NOTHING WAS DONE. The draft is kept in the preparation stage.",
  "Kullanıcı onayladı: Yayımlamayı onaylıyorum": "The user approved: I approve publishing",
  "Senin onayını bekliyor: Taslakların yayımlanması": "Waiting for your approval: Publishing the drafts",
  "Önceki adımların çıktılarını ve gerçek rakamlarını gözden geçir; neyi değiştireceğine sen karar ver.": "Review the outputs and real figures of the previous steps; you decide what to change.",
