  "Süre bitirildi.": "Zeit beendet.",
  "Bu tekrarlayan kayıt silinsin mi? Daha önce eklenen kayıtlar kalır.": "Diesen wiederkehrenden Eintrag löschen? Bereits hinzugefügte Einträge bleiben bestehen.",
