  "Aboneliği bitirmek istediğinden emin misin? (test) Kurduğun iş sende kalır, otomasyonlar durur.": "Möchtest du das Abonnement wirklich beenden? (Test) Das Geschäft, das du aufgebaut hast, bleibt bei dir; die Automatisierungen stoppen.",
  "PIN'i kurtarmanın yolu yok: kilidi açmak için uygulama verileri silinir. Devam edilsin mi?": "Die PIN kann nicht wiederhergestellt werden: Zum Entsperren werden die App-Daten gelöscht. Fortfahren?",
  "Yedekteki # kayıt ve # proje yüklenecek. Şu anki verilerinin yerine geçer. Devam edilsin mi?": "# Einträge und # Projekte aus der Sicherung werden geladen. Das ersetzt deine aktuellen Daten. Fortfahren?",
  "Tüm verilerin kalıcı olarak silinecek. Emin misin?": "Alle deine Daten werden dauerhaft gelöscht. Bist du sicher?",
  "Ana sayfa": "Start",
