  "# / # proje": "# / # Projekte",
  "Seçtiğin modele göre günlük iş planı hazırlama (şu an hazır şablonlarla; yapay zekâ bağlantısı yakında)": "Tagesplan für das gewählte Modell erstellen (derzeit aus Vorlagen; KI-Anbindung folgt bald)",
  "Yapay zekâ plan ve taslakları hazırlar; harcama ve dış işlemlerde senden onay ister (gerçek yapay zekâ bağlantısı yakında)": "Die KI bereitet Pläne und Entwürfe vor und holt bei Ausgaben und externen Aktionen deine Zustimmung ein (echte KI-Anbindung folgt bald)",
  "# / # proje. Az ve odaklı proje, dağınık çok işten daha iyi ilerler.": "# / # Projekte. Wenige, fokussierte Projekte kommen schneller voran als viele verstreute.",
  "Henüz projen yok. Sana uygun gelir modelini bulup ilk projeni başlatabilirsin.": "Du hast noch keine Projekte. Finde das passende Einkommensmodell und starte dein erstes Projekt.",
  "Yeni proje başlatmak için Manuel veya üstü paket gerekir.": "Für ein neues Projekt brauchst du den Tarif „Manuell\" oder höher.",
  "Paketin hesabına bağlıdır. Otomasyon planları ve karar kartları aktif projen için hazırlanır. Projeyi değiştirsen de gelir-gider kayıtların kaybolmaz.": "Dein Tarif ist an dein Konto gebunden. Automatisierungspläne und Entscheidungskarten werden für dein aktives Projekt erstellt. Deine Einnahmen- und Ausgabeneinträge gehen beim Wechsel des Projekts nicht verloren.",
  "Başlangıç maliyeti": "Startkosten",
