  "Risk": "Risiko",
  "Gelirin çalıştığın saate bağlıdır ve düzensiz olabilir. Pasif değildir; zamanını işe çevirirsin.": "Dein Einkommen hängt von deinen Arbeitsstunden ab und kann unregelmäßig sein. Es ist nicht passiv; du verwandelst deine Zeit in Arbeit.",
  "Reddedilmeyi göze almak gerekir; işletmeler yavaş karar verebilir. Pasif değildir, bir hizmet işidir.": "Du musst Absagen aushalten; Unternehmen entscheiden mitunter langsam. Es ist nicht passiv, sondern ein Dienstleistungsjob.",
  "Görsel üretim": "Visuelle Produktion",
  "Yazı": "Schreiben",
  "Emeğin karşılığı geç gelebilir; erişim ve takipçi sayısı senin kontrolünde değildir.": "Der Lohn für deine Mühe kann spät kommen; Reichweite und Followerzahl hast du nicht in der Hand.",
  "Şimdilik önerilmeyenler": "Vorerst nicht empfohlen",
  "Düşük": "Niedrig",
  "Zor": "Schwer",
  "Arama motorlarında görünmek aylar sürebilir; ortaklık şartları ve arama kuralları senin kontrolünde değildir.": "Das Erscheinen in Suchmaschinen kann Monate dauern; Partnerbedingungen und Suchregeln liegen nicht in deiner Hand.",
  "Alan adı ve barındırma için küçük bir bütçe gerekir; şimdilik başka modellerle başla.": "Für Domain und Hosting braucht es ein kleines Budget; starte vorerst mit anderen Modellen.",
  "Ürünü hazırlamak yetmez; doğru insanlara ulaşmak için pazarlama emeği gerekir ve satış olmayabilir.": "Das Produkt zu erstellen reicht nicht; du brauchst Marketingaufwand, um die richtigen Menschen zu erreichen, und Verkäufe sind nicht sicher.",
