  "Öncelik:": "Priorität:",
  "Oluşturuldu:": "Erstellt:",
  "Projenin cihazdaki durumunu, görev ilerlemesini ve onaylı hafızasını özetle.": "Fasse den Zustand des Projekts auf dem Gerät, den Aufgabenfortschritt und das genehmigte Gedächtnis zusammen.",
