  "Aboneliği bitirmek istediğinden emin misin? (test) Kurduğun iş sende kalır, otomasyonlar durur.": "¿Seguro que quieres terminar la suscripción? (prueba) El negocio que construiste se queda contigo; las automatizaciones se detienen.",
  "PIN'i kurtarmanın yolu yok: kilidi açmak için uygulama verileri silinir. Devam edilsin mi?": "No hay forma de recuperar el PIN: para desbloquear se borrarán los datos de la app. ¿Continuar?",
