  "Yapay zekâ plan ve taslakları hazırlar; harcama ve dış işlemlerde senden onay ister (gerçek yapay zekâ bağlantısı yakında)": "La IA prepara planes y borradores y te pide aprobación para gastos y acciones externas (la conexión real con IA llegará pronto)",
  "# / # proje. Az ve odaklı proje, dağınık çok işten daha iyi ilerler.": "# / # proyectos. Pocos proyectos enfocados avanzan más rápido que muchos dispersos.",
  "Henüz projen yok. Sana uygun gelir modelini bulup ilk projeni başlatabilirsin.": "Aún no tienes proyectos. Encuentra el modelo de ingresos que te conviene y empieza tu primer proyecto.",
  "Yeni proje başlatmak için Manuel veya üstü paket gerekir.": "Para empezar un proyecto nuevo se necesita el plan Manual o superior.",
  "Paketin hesabına bağlıdır. Otomasyon planları ve karar kartları aktif projen için hazırlanır. Projeyi değiştirsen de gelir-gider kayıtların kaybolmaz.": "Tu plan está vinculado a tu cuenta. Los planes de automatización y las tarjetas de decisión se preparan para tu proyecto activo. Tus movimientos de ingresos y gastos no se pierden al cambiar de proyecto.",
