  "Emeğin karşılığı geç gelebilir; erişim ve takipçi sayısı senin kontrolünde değildir.": "La recompensa de tu esfuerzo puede tardar; el alcance y el número de seguidores no dependen de ti.",
  "Şimdilik önerilmeyenler": "No recomendados por ahora",
