  "Arama motorlarında görünmek aylar sürebilir; ortaklık şartları ve arama kuralları senin kontrolünde değildir.": "Aparecer en los buscadores puede tardar meses; las condiciones de afiliación y las reglas de búsqueda no dependen de ti.",
  "Alan adı ve barındırma için küçük bir bütçe gerekir; şimdilik başka modellerle başla.": "Se necesita un pequeño presupuesto para dominio y alojamiento; empieza por ahora con otros modelos.",
