  "aktif proje. Az ve odaklı proje, dağınık çok işten daha iyi ilerler.": "proyectos activos. Pocos proyectos enfocados rinden más que muchos dispersos.",
  "Paketin hesabına bağlıdır; otomasyon paketini bir projene atayabilirsin. Projeyi değiştirsen de gelir-gider kayıtların kaybolmaz.": "Tu plan pertenece a tu cuenta; puedes asignar tu plan de automatización a un proyecto. Cambiar de proyecto nunca hace desaparecer tus registros de ingresos y gastos.",
