  "kaydın hiçbir projeye bağlı değil (eski kayıtlar). Hepsini bu projeye bağlayabilirsin; kayıtlar silinmez, istediğinde tek tek yeniden değiştirebilirsin.": "de tus registros no están vinculados a ningún proyecto (registros antiguos). Puedes vincularlos todos a este proyecto; no se borra nada y luego puedes cambiarlos uno a uno.",
