  "Paket": "Plan",
  "Bu projede paket yok; proje paketsiz de kullanılabilir.": "Este proyecto no tiene plan; se puede usar sin él.",
  "Atanabilir bir otomasyon paketin yok. Paketler hesabına bağlıdır (Hesabım › Paketler, test modu).": "No tienes un plan de automatización para asignar. Los planes pertenecen a tu cuenta (Mi cuenta › Planes, modo de prueba).",
