  "Projeyi sil": "Eliminar proyecto",
  "Silmeden önce arşivlemeyi düşün: arşivde hiçbir veri kaybolmaz. Silersen projenin görevleri, notları, planları ve kararları gider; gelir-gider kayıtların kalır ve “Genel”e döner. Silmeden önce dışa aktarabilirsin.": "Considera archivar antes de eliminar: en el archivo no se pierde nada. Si eliminas, se borran las tareas, notas, planes y decisiones del proyecto; tus registros de ingresos y gastos se conservan y vuelven a “General”. Puedes exportar antes.",
  "Bu proje ne hakkında?": "¿De qué trata este proyecto?",
  "İsteğe bağlı": "Opcional",
  "Yeni proje oluştur": "Crear proyecto nuevo",
  "Paketimi bu projeye ata": "Asignar mi plan a este proyecto",
  "Aktif yap": "Activar",
  "Proje sınırına ulaştın.": "Has llegado al límite de proyectos.",
  "Aynı anda en fazla # aktif proje yürütebilirsin; böylece dağılmadan ilerlersin. Yeni proje için bir projeni arşivleyebilirsin: arşivlenen projenin hiçbir verisi silinmez.": "Puedes llevar como máximo # proyectos activos a la vez para mantener el enfoque. Para empezar uno nuevo, archiva un proyecto: en un proyecto archivado no se elimina nada.",
  "Bu projeye bağlı kayıt yok. Kayıt eklerken “Hangi iş için?” alanından bu projeyi seçebilirsin.": "Ningún registro está vinculado a este proyecto. Al añadir un registro, elige este proyecto en “¿Para qué trabajo?”.",
  "Arşiv (#)": "Archivo (#)",
