  "Hesabındaki otomasyon paketi bu projeye atanmış. (TEST MODU: gerçek ödeme yok.)": "El plan de automatización de tu cuenta está asignado a este proyecto. (MODO DE PRUEBA: sin pago real.)",
  "Paketi bu projeden kaldır": "Quitar el plan de este proyecto",
  "Paket şu an aktif değil": "Plan no activo ahora mismo",
  "Bu projeye atanmış paket şu an hesabında aktif değil. Projenin verileri, geçmişi ve görevleri olduğu gibi duruyor. Hesabındaki aktif paketi atayabilir ya da atamayı kaldırabilirsin.": "El plan asignado a este proyecto no está activo en tu cuenta ahora mismo. Los datos, el historial y las tareas del proyecto siguen intactos. Puedes asignar tu plan activo o quitar la asignación.",
  "Atamayı kaldır": "Quitar asignación",
