  "Proje arşivlendi.": "Proyecto archivado.",
  "En fazla # aktif proje olabilir. Önce birini arşivle.": "Puedes tener como máximo # proyectos activos. Archiva uno primero.",
  "Proje arşivden çıkarıldı.": "Proyecto sacado del archivo.",
  "Proje silindi.": "Proyecto eliminado.",
