  "Yapay zekâ (demo, kural tabanlı) planı hazırladı. Onayını bekliyor.": "La IA (demostración, basada en reglas) preparó el plan. Esperando tu aprobación.",
  "Açıklama": "Descripción",
  "Sonuç / çıktı (kendi notun)": "Resultado / salida (tu propia nota)",
  "Kime hizmet edeceğini netleştirmek için araştırma soru listesi taslağı hazırla.": "Prepara un borrador de lista de preguntas de investigación para aclarar a quién vas a servir.",
  "Bağımlı olduğu görevler:": "Depende de estas tareas:",
  "Projenin gelir modeline uygun ürün/içerik fikirleri taslağı çıkar.": "Esboza ideas de producto/contenido acordes con el modelo de ingresos del proyecto.",
  "Dört haftalık bir geliştirme iskeleti hazırla. Yaklaşımı sen seçersin.": "Prepara un esquema de desarrollo de cuatro semanas. El enfoque lo eliges tú.",
  "Hangi yaklaşımla ilerleyelim?": "¿Con qué enfoque seguimos?",
  "İki yaklaşım var; ikisinde de sonuç garanti değildir.": "Hay dos enfoques; ninguno garantiza un resultado.",
  "A: Düşük maliyet, yavaş ilerleme": "A: Bajo coste, progreso lento",
  "Tamamlandı. Rapor: Dört haftalık plan iskeleti hazırlandı (A seçildi).": "Completada. Informe: esquema del plan de cuatro semanas preparado (se eligió A).",
  "İşlem gerçekleştirildi: seçimin plana işlendi (A).": "Acción realizada: tu elección se aplicó al plan (A).",
  "Kullanıcı onayladı: A: Düşük maliyet, yavaş ilerleme": "El usuario aprobó: A: Bajo coste, progreso lento",
  "Senin onayını bekliyor: Hangi yaklaşımla ilerleyelim?": "Esperando tu aprobación: ¿Con qué enfoque seguimos?",
  "Tanıtım gönderileri için taslaklar hazırla. Yayımlama ayrı bir onay ister ve şu an yapılamaz.": "Prepara borradores para publicaciones promocionales. Publicar requiere una aprobación aparte y ahora no se puede hacer.",
  "Taslakların yayımlanması": "Publicación de los borradores",
  "Hazırlanan taslakları yayımlamak istiyor musun?": "¿Quieres publicar los borradores preparados?",
  "Yayımlamayı onaylıyorum": "Apruebo la publicación",
  "Bu işlem yapılmadı:": "Esta acción no se realizó:",
  "Bağlı hesap yok; yayımlama yapılmaz. Taslak hazır; işlemi sen kendin yapabilirsin.": "No hay cuenta conectada; no se publica nada. El borrador está listo; puedes hacer la acción tú mismo.",
  "Ben yaptım, tamamla": "Lo hice yo, completar",
  "Düzenle": "Editar",
  "Başarısız say": "Marcar como fallida",
  "İptal et": "Cancelar",
  "Onay kaydedildi, ama \"İçerik yayımlama\" bu sürümde desteklenmiyor: HİÇBİR İŞLEM YAPILMADI. Taslak hazırlık aşamasında tutuluyor.": "Aprobación registrada, pero «Publicar contenido» no es compatible en esta versión: NO SE HIZO NADA. El borrador se mantiene en preparación.",
  "Kullanıcı onayladı: Yayımlamayı onaylıyorum": "El usuario aprobó: Apruebo la publicación",
  "Senin onayını bekliyor: Taslakların yayımlanması": "Esperando tu aprobación: Publicación de los borradores",
  "Önceki adımların çıktılarını ve gerçek rakamlarını gözden geçir; neyi değiştireceğine sen karar ver.": "Revisa los resultados y las cifras reales de los pasos anteriores; tú decides qué cambiar.",
  "Hazırlığı başlat": "Iniciar preparación",
  "# gün ertele": "Aplazar # días",
  "Önce şunlar tamamlanmalı:": "Antes hay que completar estas:",
  "Ertelendi:": "Aplazada:",
  "Ertelemeyi kaldır": "Quitar el aplazamiento",
  "Kullanıcı görevi # tarihine erteledi.": "El usuario aplazó la tarea al #.",
  "Başarısız: neden belirtilmedi": "Fallida: no se indicó el motivo",
  "Hazırlık başlayınca onayına sunulur.": "Se somete a tu aprobación cuando empiece la preparación.",
  "Onay bekleyen öneriler": "Sugerencias esperando aprobación",
  "Sohbette yazdıkların önemli görünüyordu. Sen onaylamazsan saklanmaz.": "Lo que escribiste en el chat parecía importante. No se guarda si no lo apruebas.",
  "Plan onaylandı. Görevleri tek tek sen başlatırsın.": "Plan aprobado. Tú inicias las tareas una a una.",
  "Plan reddedildi; hiçbir görev çalışmadı.": "Plan rechazado; no se ejecutó ninguna tarea.",
  "Hazırlık yapıldı.": "Preparación hecha.",
  "Onayın kaydedildi, ama bu işlem bu sürümde desteklenmiyor: hiçbir şey yapılmadı.": "Tu aprobación quedó registrada, pero esta acción no es compatible en esta versión: no se hizo nada.",
  "Onaylandı ve raporlandı.": "Aprobada e informada.",
  "Onaylanmadı; işlem yapılmadı, görev iptal edildi.": "No aprobada; no se hizo ninguna acción y la tarea se canceló.",
  "Başarısız olarak işaretlendi.": "Marcada como fallida.",
  "Bu görev iptal edilsin mi?": "¿Cancelar esta tarea?",
  "Görev iptal edildi.": "Tarea cancelada.",
  "Görev yeniden planlandı.": "Tarea replanificada.",
  "Görev ertelendi.": "Tarea aplazada.",
  "Erteleme kaldırıldı.": "Aplazamiento quitado.",
  "Bu görev ve işlem geçmişi silinsin mi? Bu işlem geri alınamaz.": "¿Eliminar esta tarea y su historial de acciones? No se puede deshacer.",
  "Görev silindi.": "Tarea eliminada.",
  "Görev güncellendi.": "Tarea actualizada.",
  "Görev eklendi.": "Tarea añadida.",
  "İşlem yapılamadı.": "No se pudo realizar la acción.",
  "NORA": "NORA",
  "Düşünür. Öğrenir. Planlar. Geliştirir.": "Piensa. Aprende. Planifica. Mejora.",
  "Merhaba, ben NORA! Anlamadığın bir terimi veya görevi yaz; bir hedefin varsa \"…geliştirmek istiyorum\" diye yaz, Görev Merkezi için plan taslağı hazırlayayım.": "¡Hola, soy NORA! Escribe un término o tarea que no entiendas; si tienes un objetivo, escribe «…quiero hacer crecer…» y prepararé un borrador de plan para el Centro de tareas.",
  "NORA erişimi: bu test sürümünde tüm paketlerde açık. İleride ücretli paketle kontrol edilecek; şu an gerçek bir abonelik veya ödeme yoktur.": "Acceso a NORA: abierto en todos los paquetes en esta versión de prueba. Más adelante se controlará con un paquete de pago; ahora no existe una suscripción ni un pago reales.",
  "Ben NORA, Pasif Gelirim'in içindeki yapay zekâ asistanın. Düşünür, öğrenir, planlar, geliştiririm. Projelerinin görev ve hafıza bilgisini yalnızca izin verdiğin kadarıyla kullanırım; önemli bir şey yapmadan önce her zaman onayını isterim. (Şu an demo modundayım: kurallara göre yanıt veriyorum, gerçek bir model yazmıyor.)": "Soy NORA, la asistente de IA dentro de Pasif Gelirim. Pienso, aprendo, planifico y mejoro. Uso la información de tareas y memoria de tus proyectos solo hasta donde lo permitas, y siempre pido tu aprobación antes de hacer algo importante. (Ahora estoy en modo demostración: respondo por reglas, ningún modelo real escribe esto.)",
  "Genel sohbettesin; hiçbir projenin görevine bakmıyorum. \"Proje sohbeti\"ne geçersen o projenin Görev Merkezi durumunu söyleyebilirim.": "Estás en el chat general; no miro las tareas de ningún proyecto. Si cambias a «Chat del proyecto», puedo decirte el estado del Centro de tareas de ese proyecto.",
  "# açık görev": "# tareas abiertas",
