  "Fikirlerini, işlerini ve araştırmalarını bir arada tut": "Mantén tus ideas, trabajo e investigación en un solo lugar",
  "# not": "# notas",
  "Notların bu cihazda saklanır, JSON yedeğine girer ve sunucuya gönderilmez.": "Tus notas se guardan en este dispositivo, se incluyen en la copia de seguridad JSON y nunca se envían a un servidor.",
