  "Bu tekrarlayan kayıt silinsin mi? Daha önce eklenen kayıtlar kalır.": "Удалить эту регулярную запись? Уже добавленные записи останутся.",
  "Bu birikim hedefi silinsin mi?": "Удалить эту цель накопления?",
  "Bu kayıt silinsin mi?": "Удалить эту запись?",
  "Aboneliği bitirmek istediğinden emin misin? (test) Kurduğun iş sende kalır, otomasyonlar durur.": "Ты уверен, что хочешь завершить подписку? (тест) Построенный тобой бизнес остаётся у тебя; автоматизации останавливаются.",
  "PIN'i kurtarmanın yolu yok: kilidi açmak için uygulama verileri silinir. Devam edilsin mi?": "Восстановить PIN невозможно: для разблокировки данные приложения будут удалены. Продолжить?",
  "Yedekteki # kayıt ve # proje yüklenecek. Şu anki verilerinin yerine geçer. Devam edilsin mi?": "Из резервной копии будет загружено # записей и # проектов. Это заменит текущие данные. Продолжить?",
  "Tüm verilerin kalıcı olarak silinecek. Emin misin?": "Все твои данные будут удалены навсегда. Ты уверен?",
  "Ana sayfa": "Главная",
