  "Seçtiğin modele göre günlük iş planı hazırlama (şu an hazır şablonlarla; yapay zekâ bağlantısı yakında)": "Составлять дневной рабочий план по выбранной модели (пока по готовым шаблонам; подключение ИИ скоро)",
  "Yapay zekâ plan ve taslakları hazırlar; harcama ve dış işlemlerde senden onay ister (gerçek yapay zekâ bağlantısı yakında)": "ИИ готовит планы и черновики и запрашивает твоё согласие на расходы и внешние действия (настоящее подключение ИИ скоро)",
  "# / # proje. Az ve odaklı proje, dağınık çok işten daha iyi ilerler.": "# / # проектов. Немного сфокусированных проектов движутся быстрее, чем много разрозненных.",
  "Henüz projen yok. Sana uygun gelir modelini bulup ilk projeni başlatabilirsin.": "У тебя пока нет проектов. Найди подходящую модель дохода и начни первый проект.",
  "Yeni proje başlatmak için Manuel veya üstü paket gerekir.": "Чтобы начать новый проект, нужен тариф «Ручной» или выше.",
  "Paketin hesabına bağlıdır. Otomasyon planları ve karar kartları aktif projen için hazırlanır. Projeyi değiştirsen de gelir-gider kayıtların kaybolmaz.": "Тариф привязан к твоему аккаунту. Планы автоматизации и карточки решений готовятся для активного проекта. Записи о доходах и расходах не пропадают при смене проекта.",
