  "Gelirin çalıştığın saate bağlıdır ve düzensiz olabilir. Pasif değildir; zamanını işe çevirirsin.": "Твой доход зависит от отработанных часов и может быть нерегулярным. Это не пассивный доход; ты превращаешь время в работу.",
  "Reddedilmeyi göze almak gerekir; işletmeler yavaş karar verebilir. Pasif değildir, bir hizmet işidir.": "Нужно быть готовым к отказам; компании могут решать медленно. Это не пассивный доход, а работа в сфере услуг.",
  "Görsel üretim": "Визуальное производство",
