  "Arama motorlarında görünmek aylar sürebilir; ortaklık şartları ve arama kuralları senin kontrolünde değildir.": "Появление в поисковиках может занять месяцы; условия партнёрок и правила поиска от тебя не зависят.",
  "Alan adı ve barındırma için küçük bir bütçe gerekir; şimdilik başka modellerle başla.": "Для домена и хостинга нужен небольшой бюджет; пока начни с других моделей.",
  "Ürünü hazırlamak yetmez; doğru insanlara ulaşmak için pazarlama emeği gerekir ve satış olmayabilir.": "Подготовить продукт недостаточно; нужны маркетинговые усилия, чтобы дойти до нужных людей, и продаж может не быть.",
