  "Verini yalnızca sen silebilirsin.": "Удалить свои данные можешь только ты.",
  "Harici hesapta değişiklik": "Изменения во внешнем аккаунте",
  "OAuth/API entegrasyonu yok.": "Интеграции OAuth/API нет.",
  "Hedefini bir görev planına böldüm (demo yapay zekâ: kural tabanlı şablon, gerçek model yazmadı). Plan şimdilik yalnızca TASLAK; aşağıdaki karttan onaylarsan görevler başlatılabilir, onaylamazsan hiçbiri çalışmaz. Para harcama, yayımlama veya mesaj gönderme gibi adımlar için ayrıca onayını isterim; bu sürümde dış hesaplara bağlı olmadığım için bunları yapamam.": "Я разбил твою цель на план задач (демо-ИИ: шаблон по правилам, настоящая модель его не писала). Пока план — только ЧЕРНОВИК; если одобришь его в карточке ниже, задачи можно будет запускать, если нет — ни одна не выполнится. Для шагов вроде траты денег, публикации или отправки сообщений я отдельно спрошу твоё одобрение; в этой версии я не подключён к внешним аккаунтам, поэтому не могу их выполнять.",
  "Görev planı bir projeye bağlı olmalı. Genel sohbetteyken plan oluşturmuyorum; \"Proje sohbeti\"ne geçip (veya bir proje başlatıp) hedefini tekrar yaz.": "План задач должен принадлежать проекту. В общем чате я планов не создаю; перейди в «Чат проекта» (или начни проект) и напиши цель ещё раз.",
  "Bilinmeyen yetenek.": "Неизвестная возможность.",
  "Bu sürümde bu işlem için bir bağlantı yok; izin verilemez.": "В этой версии для этого действия нет подключения; разрешение дать нельзя.",
  "Proje bulunamadı veya arşivde; görevleri değiştirilemez.": "Проект не найден или в архиве; его задачи изменить нельзя.",
