  "Görev merkezi": "Центр задач",
  "# açık · # onay bekliyor": "# открыто · # ждут одобрения",
  "Yapay zekâ destekli görev planı. Her adım senin onayınla ilerler.": "План задач с помощью ИИ. Каждый шаг идёт дальше только с твоего одобрения.",
  "Görev merkezine git": "Перейти в центр задач",
  "Görev Merkezi": "Центр задач",
  "# açık": "# открыто",
  "Akış: planla → hazırla → seçenek sun → onay al → desteklenen işlemi yap → raporla. Burada yapay zekâ kendi başına işlem yapmaz; her adımı sen onaylarsın. Görevler yalnızca bu projeye aittir.": "Порядок: спланировать → подготовить → предложить варианты → получить одобрение → выполнить поддерживаемое действие → отчитаться. Здесь ИИ ничего не делает сам; каждый шаг одобряешь ты. Задачи относятся только к этому проекту.",
  "Onay bekleyenler": "Ждут одобрения",
  "Şu an onayını bekleyen bir işlem yok.": "Сейчас нет действий, ожидающих твоего одобрения.",
  "Henüz görev yok. Sohbette \"Dijital ürün projemi geliştirmek istiyorum\" gibi bir hedef yaz, plan taslağı hazırlansın; ya da aşağıdan kendin görev ekle.": "Задач пока нет. Напиши в чате цель, например «Хочу развить проект цифровых продуктов», и будет подготовлен черновик плана; или добавь задачу сам ниже.",
  "Sohbete git": "В чат",
  "Yeni görev": "Новая задача",
  "Görev adı": "Название задачи",
  "Öncelik": "Приоритет",
  "Dış işlemler ve izinler": "Внешние действия и разрешения",
  "Bu sürümde hiçbir dış hesaba (sosyal medya, e-posta, ödeme, web sitesi) bağlı değilim ve şifre/OAuth istemem. Aşağıdaki işlemler yapılmaz; yalnızca taslak hazırlanır. İleride bir bağlantı eklenirse her biri ayrı izinle ve her seferinde onayınla çalışır.": "В этой версии я не подключён ни к каким внешним аккаунтам (соцсети, почта, оплата, сайт) и никогда не прошу пароли/OAuth. Действия ниже не выполняются; готовятся только черновики. Если позже появится подключение, каждое будет работать по отдельному разрешению и каждый раз с твоего одобрения.",
  "Bu cihazda": "На этом устройстве",
  "Bağlı değil": "Не подключено",
  "Paket:": "Пакет:",
  "tüm paketlerde şimdilik aynı temel görev motoru kullanılır.": "пока во всех пакетах используется один и тот же базовый механизм задач.",
