  "Projenin gelir modeline uygun ürün/içerik fikirleri taslağı çıkar.": "Набросай идеи продуктов/контента, подходящие модели дохода проекта.",
  "Dört haftalık bir geliştirme iskeleti hazırla. Yaklaşımı sen seçersin.": "Подготовь четырёхнедельный план развития. Подход выбираешь ты.",
