  "İşlem gerçekleştirildi: seçimin plana işlendi (A).": "Действие выполнено: твой выбор внесён в план (A).",
  "Kullanıcı onayladı: A: Düşük maliyet, yavaş ilerleme": "Пользователь одобрил: A: Низкие затраты, медленный прогресс",
  "Senin onayını bekliyor: Hangi yaklaşımla ilerleyelim?": "Ждёт твоего одобрения: Каким подходом пойдём?",
  "Tanıtım gönderileri için taslaklar hazırla. Yayımlama ayrı bir onay ister ve şu an yapılamaz.": "Подготовь черновики рекламных постов. Публикация требует отдельного одобрения и сейчас невозможна.",
  "Taslakların yayımlanması": "Публикация черновиков",
  "Hazırlanan taslakları yayımlamak istiyor musun?": "Хочешь опубликовать подготовленные черновики?",
