  "Bu işlem yapılmadı:": "Это действие не выполнено:",
  "Bağlı hesap yok; yayımlama yapılmaz. Taslak hazır; işlemi sen kendin yapabilirsin.": "Аккаунт не подключён; ничего не публикуется. Черновик готов; действие можешь выполнить сам.",
  "Ben yaptım, tamamla": "Я сделал сам, завершить",
  "Düzenle": "Изменить",
  "Başarısız say": "Отметить как неудавшуюся",
  "İptal et": "Отменить",
  "Onay kaydedildi, ama \"İçerik yayımlama\" bu sürümde desteklenmiyor: HİÇBİR İŞLEM YAPILMADI. Taslak hazırlık aşamasında tutuluyor.": "Одобрение записано, но «Публикация контента» в этой версии не поддерживается: НИЧЕГО НЕ СДЕЛАНО. Черновик остаётся на этапе подготовки.",
  "Kullanıcı onayladı: Yayımlamayı onaylıyorum": "Пользователь одобрил: Одобряю публикацию",
  "Senin onayını bekliyor: Taslakların yayımlanması": "Ждёт твоего одобрения: Публикация черновиков",
  "Önceki adımların çıktılarını ve gerçek rakamlarını gözden geçir; neyi değiştireceğine sen karar ver.": "Просмотри результаты и реальные цифры предыдущих шагов; что менять — решаешь ты.",
