  "Onay bekleyen öneriler": "Предложения, ожидающие одобрения",
  "Sohbette yazdıkların önemli görünüyordu. Sen onaylamazsan saklanmaz.": "То, что ты написал в чате, показалось важным. Без твоего одобрения не сохраняется.",
  "Plan onaylandı. Görevleri tek tek sen başlatırsın.": "План одобрен. Задачи ты запускаешь по одной.",
