  "Aktif yap": "اجعله نشطًا",
  "Proje sınırına ulaştın.": "وصلت إلى حد المشاريع.",
  "Aynı anda en fazla # aktif proje yürütebilirsin; böylece dağılmadan ilerlersin. Yeni proje için bir projeni arşivleyebilirsin: arşivlenen projenin hiçbir verisi silinmez.": "يمكنك إدارة # مشاريع نشطة كحد أقصى في الوقت نفسه لتبقى مركّزًا. لبدء مشروع جديد، أرشف مشروعًا: لا يُحذف شيء من المشروع المؤرشف.",
  "Bu projeye bağlı kayıt yok. Kayıt eklerken “Hangi iş için?” alanından bu projeyi seçebilirsin.": "لا توجد سجلات مرتبطة بهذا المشروع. عند إضافة سجل، اختر هذا المشروع من «لأي عمل؟».",
  "Arşiv (#)": "الأرشيف (#)",
  "Arşivde": "مؤرشف",
  "Arşivden çıkar": "استعادة من الأرشيف",
  "Proje hedefi (gelir)": "هدف المشروع (الدخل)",
  "%# · Hedefe # TL kaldı": "%# · تبقّى # TL للوصول إلى الهدف",
  "Son # kayıt gösteriliyor (# kayıt).": "تُعرض آخر # سجلات (# سجلات).",
  "Hesabındaki otomasyon paketi bu projeye atanmış. (TEST MODU: gerçek ödeme yok.)": "باقة الأتمتة في حسابك معيّنة لهذا المشروع. (وضع تجريبي: لا يوجد دفع حقيقي.)",
  "Paketi bu projeden kaldır": "إزالة الباقة من هذا المشروع",
  "Paket şu an aktif değil": "الباقة غير نشطة حاليًا",
  "Bu projeye atanmış paket şu an hesabında aktif değil. Projenin verileri, geçmişi ve görevleri olduğu gibi duruyor. Hesabındaki aktif paketi atayabilir ya da atamayı kaldırabilirsin.": "الباقة المعيّنة لهذا المشروع غير نشطة في حسابك حاليًا. بيانات المشروع وسجله ومهامه كما هي دون أي تغيير. يمكنك تعيين باقتك النشطة أو إزالة التعيين.",
  "Atamayı kaldır": "إزالة التعيين",
  "Proje adı boş olamaz.": "لا يمكن أن يكون اسم المشروع فارغًا.",
  "Proje hedefi geçerli bir tutar olmalı.": "يجب أن يكون هدف المشروع مبلغًا صالحًا.",
  "Proje kaydedildi.": "تم حفظ المشروع.",
  "Proje arşivlendi.": "تمت أرشفة المشروع.",
  "En fazla # aktif proje olabilir. Önce birini arşivle.": "يمكن أن يكون لديك # مشاريع نشطة كحد أقصى. أرشف أحدها أولًا.",
  "Proje arşivden çıkarıldı.": "تمت استعادة المشروع من الأرشيف.",
  "Proje silindi.": "تم حذف المشروع.",
  "# kayıt projeye bağlandı.": "تم ربط # سجلات بالمشروع.",
  "Paket bu projeye taşındı.": "تم نقل الباقة إلى هذا المشروع.",
  "Paket projeye atandı.": "تم تعيين الباقة للمشروع.",
  "Paket ataması kaldırıldı.": "تمت إزالة تعيين الباقة.",
  "Aktif proje değişti.": "تم تغيير المشروع النشط.",
  "Arşivdeki projeye paket atanamaz.": "لا يمكن تعيين باقة لمشروع مؤرشف.",
  "Atayabileceğin bir otomasyon paketin yok.": "لا توجد لديك باقة أتمتة لتعيينها.",
  "Bu proje arşivlensin mi? Hiçbir veri silinmez; proje Arşiv bölümüne taşınır ve istediğin zaman geri alabilirsin. Projeye atanmış paket varsa atama kalkar.": "هل تريد أرشفة هذا المشروع؟ لن يُحذف شيء؛ سينتقل إلى قسم الأرشيف ويمكنك استعادته في أي وقت. وإذا كانت له باقة معيّنة فسيُلغى تعيينها.",
  "Bu proje kalıcı olarak silinsin mi? Silinecek: görevler, notlar, planlar ve kararlar. Silinmeyecek: gelir-gider kayıtların (Genel'e döner). Bu işlem geri alınamaz. Emin değilsen İptal'e bas ve projeyi arşivle.": "هل تريد حذف هذا المشروع نهائيًا؟ سيُحذف: المهام والملاحظات والخطط والقرارات. وسيبقى: سجلات دخلك ومصروفاتك (تعود إلى «عام»). لا يمكن التراجع عن ذلك. إذا لم تكن متأكدًا فاضغط إلغاء وأرشف المشروع بدلًا من ذلك.",
  "Projeye bağlı olmayan tüm kayıtların bu projeye bağlansın mı? Kayıtlar silinmez; sonra tek tek değiştirebilirsin.": "هل تريد ربط كل السجلات غير المرتبطة بأي مشروع بهذا المشروع؟ لن يُحذف شيء؛ ويمكنك تعديلها لاحقًا واحدًا واحدًا.",
  "Paket şu an bu projede:": "الباقة معيّنة حاليًا للمشروع:",
  "Paketi buraya taşı": "نقل الباقة إلى هنا",
  "Dönem neti": "صافي الفترة",
  "Fiyat": "السعر",
  "Başlangıca göre": "منذ البداية",
  "Son güncelleme: # · Fiyatlar:": "آخر تحديث: # · الأسعار بـ:",
  "Son güncelleme: #:# · Fiyatlar:": "آخر تحديث: #:# · الأسعار بـ:",
