  "Bağlı hesap yok; yayımlama yapılmaz.": "لا يوجد حساب متصل؛ لا يُنشر شيء.",
  "Mesaj veya e-posta gönderme": "إرسال الرسائل أو البريد الإلكتروني",
  "Bağlı hesap yok; gönderim yapılmaz.": "لا يوجد حساب متصل؛ لا يُرسل شيء.",
