  "Bağlı hesap yok.": "لا يوجد حساب متصل.",
  "Verini paylaşma": "مشاركة بياناتك",
  "Veri paylaşımı yapılmaz.": "لا تتم مشاركة بياناتك.",
  "Verini silme (yapay zekâ eliyle)": "حذف بياناتك (بواسطة الذكاء الاصطناعي)",
  "Verini yalnızca sen silebilirsin.": "أنت وحدك من يستطيع حذف بياناتك.",
  "Harici hesapta değişiklik": "تغييرات على حساب خارجي",
  "OAuth/API entegrasyonu yok.": "لا يوجد تكامل OAuth/API.",
  "Hedefini bir görev planına böldüm (demo yapay zekâ: kural tabanlı şablon, gerçek model yazmadı). Plan şimdilik yalnızca TASLAK; aşağıdaki karttan onaylarsan görevler başlatılabilir, onaylamazsan hiçbiri çalışmaz. Para harcama, yayımlama veya mesaj gönderme gibi adımlar için ayrıca onayını isterim; bu sürümde dış hesaplara bağlı olmadığım için bunları yapamam.": "قسّمتُ هدفك إلى خطة مهام (ذكاء اصطناعي تجريبي: قالب قائم على قواعد، ولم يكتبه نموذج حقيقي). الخطة الآن مجرد مسودة؛ إن وافقت عليها من البطاقة أدناه يمكن بدء المهام، وإن لم توافق فلن تعمل أي منها. أما خطوات مثل إنفاق المال أو النشر أو إرسال الرسائل فسأطلب موافقتك عليها على حدة؛ وفي هذا الإصدار لست متصلاً بأي حساب خارجي، لذا لا أستطيع تنفيذها.",
  "Görev planı bir projeye bağlı olmalı. Genel sohbetteyken plan oluşturmuyorum; \"Proje sohbeti\"ne geçip (veya bir proje başlatıp) hedefini tekrar yaz.": "يجب أن تنتمي خطة المهام إلى مشروع. لا أُنشئ خططاً في المحادثة العامة؛ انتقل إلى «محادثة المشروع» (أو ابدأ مشروعاً) واكتب هدفك مرة أخرى.",
  "Bilinmeyen yetenek.": "قدرة غير معروفة.",
  "Bu sürümde bu işlem için bir bağlantı yok; izin verilemez.": "لا يوجد اتصال لهذا الإجراء في هذا الإصدار؛ لا يمكن منح الإذن.",
  "Proje bulunamadı veya arşivde; görevleri değiştirilemez.": "المشروع غير موجود أو مؤرشف؛ لا يمكن تغيير مهامه.",
  "Hedefi biraz daha açık yaz (en az # karakter).": "اكتب الهدف بوضوح أكثر (# أحرف على الأقل).",
  "Şifre, PIN, kart/IBAN veya kimlik numarası gibi bilgiler hedefe yazılmamalı.": "لا يجوز كتابة معلومات مثل كلمات المرور أو الرمز السري أو البطاقة/IBAN أو أرقام الهوية في الهدف.",
  "Görev oluşturuldu (plan taslağı).": "أُنشئت المهمة (مسودة الخطة).",
