  "Çıktı taslağı hazırlandı.": "جُهّزت مسودة المخرجات.",
  "Taslak hazır; gözden geçirip tamamlayabilirsin.": "المسودة جاهزة؛ يمكنك مراجعتها وإكمال المهمة.",
