  "Yalnızca henüz başlamamış (Planlandı) görev ertelenebilir.": "لا يمكن تأجيل إلا مهمة لم تبدأ بعد (مخططة).",
  "Yalnızca tamamlanan, başarısız veya iptal edilen görev silinebilir.": "لا يمكن حذف إلا مهمة مكتملة أو فاشلة أو ملغاة.",
  "Görev merkezi": "مركز المهام",
  "# açık · # onay bekliyor": "# مفتوحة · # بانتظار الموافقة",
  "Yapay zekâ destekli görev planı. Her adım senin onayınla ilerler.": "خطة مهام بمساعدة الذكاء الاصطناعي. كل خطوة تتقدم بموافقتك فقط.",
  "Görev merkezine git": "اذهب إلى مركز المهام",
  "Görev Merkezi": "مركز المهام",
  "# açık": "# مفتوحة",
  "Akış: planla → hazırla → seçenek sun → onay al → desteklenen işlemi yap → raporla. Burada yapay zekâ kendi başına işlem yapmaz; her adımı sen onaylarsın. Görevler yalnızca bu projeye aittir.": "التسلسل: تخطيط ← تحضير ← عرض الخيارات ← أخذ الموافقة ← تنفيذ الإجراء المدعوم ← تقديم التقرير. لا يفعل الذكاء الاصطناعي هنا شيئاً من تلقاء نفسه؛ أنت توافق على كل خطوة. المهام تخص هذا المشروع فقط.",
  "Onay bekleyenler": "بانتظار الموافقة",
  "Şu an onayını bekleyen bir işlem yok.": "لا يوجد حالياً إجراء بانتظار موافقتك.",
  "Henüz görev yok. Sohbette \"Dijital ürün projemi geliştirmek istiyorum\" gibi bir hedef yaz, plan taslağı hazırlansın; ya da aşağıdan kendin görev ekle.": "لا توجد مهام بعد. اكتب في المحادثة هدفاً مثل «أريد تطوير مشروع منتجاتي الرقمية» فتُجهَّز مسودة خطة؛ أو أضف مهمة بنفسك أدناه.",
  "Sohbete git": "اذهب إلى المحادثة",
  "Yeni görev": "مهمة جديدة",
  "Görev adı": "اسم المهمة",
  "Öncelik": "الأولوية",
  "Dış işlemler ve izinler": "الإجراءات الخارجية والأذونات",
  "Bu sürümde hiçbir dış hesaba (sosyal medya, e-posta, ödeme, web sitesi) bağlı değilim ve şifre/OAuth istemem. Aşağıdaki işlemler yapılmaz; yalnızca taslak hazırlanır. İleride bir bağlantı eklenirse her biri ayrı izinle ve her seferinde onayınla çalışır.": "في هذا الإصدار لست متصلاً بأي حساب خارجي (وسائل التواصل أو البريد أو الدفع أو موقع إلكتروني) ولا أطلب كلمات المرور/OAuth أبداً. الإجراءات أدناه لا تُنفَّذ؛ تُجهَّز مسودات فقط. إن أُضيف اتصال لاحقاً فسيعمل كل واحد بإذن منفصل وبموافقتك في كل مرة.",
