  "Proje önerisi:": "اقتراح المشروع:",
  "NORA erişimi açık: bu notu Not Defteri izinlerin kapsamında görebilir. Not yalnızca bu cihazda saklanır.": "وصول NORA مفعّل: يمكنها رؤية هذه الملاحظة ضمن أذونات دفتر ملاحظاتك. تُحفظ الملاحظة على هذا الجهاز فقط.",
  "Bu metin zaten bir notta kayıtlı:": "هذا النص محفوظ بالفعل في ملاحظة:",
  "Aynı metinden ikinci bir not oluşturmak istemiyorsan Vazgeç'e bas veya mevcut notu aç.": "إذا لم ترغب في ملاحظة ثانية من النص نفسه، فاضغط «إلغاء» أو افتح الملاحظة الموجودة.",
  "Yine de kaydet": "احفظ على أي حال",
