  "Bu dönemde kayıt yok. Gelir, diğer gider veya mecburi harcama ekledikçe grafik gerçek verinle çizilir.": "لا توجد سجلات في هذه الفترة. كلما أضفت دخلًا أو مصروفات أخرى أو مصروفات إلزامية، يُرسم المخطط من بياناتك الحقيقية.",
  "Diğer gider": "مصروف آخر",
